#include <stdio.h>
#include "servo_controller.h"
int main(void){const servo_config_t cfg={0U,180U,500U,2500U,20000U};printf("map 0=%u 90=%u 180=%u us\n",servo_angle_to_pulse_us(&cfg,0U),servo_angle_to_pulse_us(&cfg,90U),servo_angle_to_pulse_us(&cfg,180U));printf("compare_1500us_1MHz=%u\n",servo_pulse_us_to_compare(1500U,1000000U));servo_controller_t c;if(!servo_controller_init(&c,&cfg,90U,15U))return 1;servo_controller_set_target(&c,250);while(!servo_controller_at_target(&c)){uint16_t p=servo_controller_step(&c);printf("angle=%u target=%u pulse=%u compare=%u\n",c.current_angle_deg,c.target_angle_deg,p,servo_pulse_us_to_compare(p,1000000U));}printf("clamp_count=%lu final=%u updates=%lu\n",(unsigned long)c.clamp_count,c.current_angle_deg,(unsigned long)c.update_count);servo_controller_set_target(&c,-30);while(!servo_controller_at_target(&c)){uint16_t p=servo_controller_step(&c);printf("return angle=%u pulse=%u\n",c.current_angle_deg,p);}printf("clamp_count=%lu final=%u\n",(unsigned long)c.clamp_count,c.current_angle_deg);return 0;}
